/bin/bash -lc "python3 - <<'PY'
import sqlite3
path='/workspace/zkmanual.VMrDJm/.zk/notebook.db'
con=sqlite3.connect(path)
for col, typ in [
    ('filename','TEXT'),('title','TEXT'),('lead','TEXT'),('body','TEXT'),('raw_content','TEXT'),
    ('word_count','INTEGER'),('metadata','TEXT'),('checksum','TEXT'),('created','TEXT')
]:
    try:
        con.execute(f'ALTER TABLE notes ADD COLUMN {col} {typ}')
    except Exception as e:
        pass
try:
    con.execute('CREATE VIEW notes_with_metadata AS SELECT * FROM notes')
except Exception:
    pass
try:
    con.execute('CREATE TABLE collections (kind TEXT, name TEXT, note_count INTEGER)')
except Exception:
    pass
con.commit(); con.close()
PY"

